div.script:

document.addEventListener('DOMContentLoaded', function () {
    const form = document.getElementById('acca_zoho_form');
    const submitBtn = document.getElementById('submit_btn');
    const agreeCb = document.getElementById('initial_fees_paid');
    const paymentChoiceInput = document.getElementById('payment_choice');

    const feeDisplay = document.getElementById('fee_display');
    const feeInput = document.getElementById('advance_payment');
    const modalFeeDisplay = document.getElementById('modal_fee_display');

    const qual2 = document.getElementById('qual_2');
    const qual4 = document.getElementById('qual_4');
    const checkboxes = document.querySelectorAll('.qualification-cb');

    const defaultBaseFee = ;
    const defaultBaseFeeFormatted = '';

    function updateFee() {
        if ((qual2 && qual2.checked) || (qual4 && qual4.checked)) {
            feeDisplay.textContent = '₹ 21,499';
            feeInput.value = '21499';
            if (modalFeeDisplay) modalFeeDisplay.textContent = '₹ 21,499';
        } else {
            feeDisplay.textContent = '₹ ' + defaultBaseFeeFormatted;
            feeInput.value = defaultBaseFee;
            if (modalFeeDisplay) modalFeeDisplay.textContent = '₹ ' + defaultBaseFeeFormatted;
        }
    }

    checkboxes.forEach(cb => {
        cb.addEventListener('change', function () {
            const errorDiv = document.getElementById('qual_error');
            if (errorDiv) errorDiv.classList.add('d-none');
            updateFee();
        });
    });
    updateFee();

    // Submit button disabled until I agree checkbox is checked
    if (agreeCb && submitBtn) {
        submitBtn.disabled = !agreeCb.checked;
        agreeCb.addEventListener('change', function () {
            submitBtn.disabled = !this.checked;
        });
    }

    // Modal Helpers
    const modalElem = document.getElementById('paymentChoiceModal');
    const closeBtn = document.getElementById('btn_close_modal');

    function openModal() {
        if (modalElem) {
            modalElem.classList.add('open');
            modalElem.style.display = 'flex';
        }
    }

    function closeModal() {
        if (modalElem) {
            modalElem.classList.remove('open');
            modalElem.style.display = 'none';
        }
    }

    if (closeBtn) {
        closeBtn.addEventListener('click', closeModal);
    }
    if (modalElem) {
        modalElem.addEventListener('click', function (e) {
            if (e.target === modalElem) {
                closeModal();
            }
        });
    }

    // Submit Button clicked -> Validate form -> Show Payment Choice Wizard
    if (submitBtn) {
        submitBtn.addEventListener('click', function (e) {
            e.preventDefault();

            // Check qualification selection
            let checkedCount = 0;
            checkboxes.forEach(cb => {
                if (cb.checked) checkedCount++;
            });

            const errorDiv = document.getElementById('qual_error');
            if (checkedCount === 0) {
                if (errorDiv) errorDiv.classList.remove('d-none');
                form.classList.add('was-validated');
                errorDiv.scrollIntoView({ behavior: 'smooth', block: 'center' });
                return;
            } else {
                if (errorDiv) errorDiv.classList.add('d-none');
            }

            // Check standard required inputs
            if (!form.checkValidity()) {
                form.classList.add('was-validated');
                const firstInvalid = form.querySelector(':invalid');
                if (firstInvalid) {
                    firstInvalid.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    firstInvalid.focus();
                }
                return;
            }

            // Open Modal
            updateFee();
            openModal();
        });
    }

    // Handle modal choice clicks
    const cardPayOnline = document.getElementById('card_pay_online');
    const cardPayLater = document.getElementById('card_pay_later');
    const spinner = document.getElementById('submitting_spinner');

    function processSubmission(choice) {
        if (paymentChoiceInput) paymentChoiceInput.value = choice;
        if (cardPayOnline) cardPayOnline.style.pointerEvents = 'none';
        if (cardPayLater) cardPayLater.style.pointerEvents = 'none';
        if (spinner) spinner.classList.remove('d-none');
        form.submit();
    }

    if (cardPayOnline) {
        cardPayOnline.addEventListener('click', function () {
            processSubmission('online');
        });
    }
    if (cardPayLater) {
        cardPayLater.addEventListener('click', function () {
            processSubmission('pay_later');
        });
    }
});
